      volume: audio.volume,
      paused: audio.paused,
      loop: audio.loop,
      currentTime: audio.currentTime,
      duration: audio.duration,
      error: !!audio.error,
      starts: probe.starts.filter((start) => start.index === probe.audio.indexOf(audio)),
    }));
